if('IntersectionObserver'in window){new IntersectionObserver(function(e){if(e[0].isIntersecting&&!seen){seen=true;start()}},{threshold:.3}).observe(SW)}else{seen=true;start()}
var rz;window.addEventListener('resize',function(){clearTimeout(rz);rz=setTimeout(function(){var ch=fit();if(ch){gen++;poster();if(seen)start()}},150)});
$$('[data-pay]').forEach(function(a){a.addEventListener('click',function(e){var p=document.getElementById('pay');if(p){e.preventDefault();p.scrollIntoView({behavior:'smooth',block:'start'})}})});
